import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import MoonLoader from "react-spinners/MoonLoader";
import "./Upload.css";

function Upload() {
  const [videoFile, setVideoFile] = useState(null);
  const [rubricFile, setRubricFile] = useState(null);
  const [rubricFileName, setRubricFileName] = useState("");
  const [transcript, setTranscript] = useState("");
  const [feedback, setFeedback] = useState("");
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState({});
  const [status, setStatus] = useState("");
  // Experimental
  const [availableRubrics, setAvailableRubrics] = useState([]);
  const [selectedRubric, setSelectedRubric] = useState("default.json");
  //End

  const navigate = useNavigate();
  const rubricInputRef = useRef(null);  // ref for hidden rubric input

  // EX Load available rubrics on mount
  useEffect(() => {
    const fetchRubrics = async () => {
      try {
        const response = await fetch("http://34.55.142.231:5000/api/rubrics");
        const data = await response.json();
        setAvailableRubrics(data);
      } catch (error) {
        console.error("Error fetching rubrics:", error);
      }
    };

    fetchRubrics();
  }, []);
  //End

  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
  };

  /* const handleRubricUpload = (event) => {
    const file = event.target.files[0];
    if (file && file.type === "text/plain") {
      setRubricFile(file);
      setRubricFileName(file.name);
      console.log("Rubric file uploaded:", file.name);
    } else {
      console.error("Please upload a valid .txt file.");
    }
  };
  */

  //EX RubricUpload
  const handleRubricUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setLoading(true);
    try {
      const formData = new FormData();
      formData.append("rubric", file);

      const response = await fetch("http://34.55.142.231:5000/api/rubrics", {
        method: "POST",
        body: formData,
      });

      const result = await response.json();
      if (response.ok) {
        setAvailableRubrics(prev => [...prev, { filename: result.filename }]);
        setSelectedRubric(result.filename);
        setRubricFileName(result.filename);
      } else {
        console.error("Upload failed:", result.error);
      }
    } catch (error) {
      console.error("Upload error:", error);
    } finally {
      setLoading(false);
    }
  };

  //End

  /* const handleAnalyze = async () => {
    console.log("Start analyzing...");
    setStatus("processing");

    const formData = new FormData();
    formData.append("video", videoFile);

    if (rubricFile) {
      formData.append("rubric", rubricFile);
    }

    try {
      const response = await fetch("http://34.55.142.231:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const errMsg = errorData.error || "Error processing video. Please try again.";
        setTranscript(errMsg);
        return;
      }

      const data = await response.json();
      console.log("Analysis Data:", data);

      setTranscript(data.transcript);
      setFeedback(data.ai_feedback);
      setAnalysis(data);
    } catch (error) {
      console.error("Error analyzing video:", error);
      setFeedback("Error processing video. Please try again.");
    }
  };
  */

  //EX Analyze
   const handleAnalyze = async () => {
    if (!videoFile) return;

    setLoading(true);
    setStatus("processing");

    const formData = new FormData();
    formData.append("video", videoFile);
    formData.append("rubric", selectedRubric);

    try {
      const response = await fetch("http://34.55.142.231:5000/api/analyze", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Analysis failed");
      }

      setTranscript(data.transcript);
      setFeedback(data.evaluation);
      setAnalysis({
        ...data,
        rubricUsed: data.rubric_used
      });

    } catch (error) {
      console.error("Analysis error:", error);
      setFeedback(error.message);
    } finally {
      setLoading(false);
      setStatus("complete");
    }
  };
  //End


  /*
  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {videoFile && status === "processing" ? (
        <div className="dashboard-content">
          {// Your processing state layout}
          <div className="loader-div">
            <MoonLoader size={50} color="#77232C" />
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {// Upload video input}
            {videoFile ? (
              <video controls>
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            ) : (
              <input type="file" accept="video/*" onChange={handleFileChange} />
            )}

            {// Analyze video button}
            <button className="save-button" onClick={handleAnalyze}>
              Analyze Video
            </button>

            {// Upload rubric button}
            <div style={{ marginTop: "10px" }}>
              <input
                ref={rubricInputRef}
                type="file"
                accept=".txt"
                id="rubric-upload"
                onChange={handleRubricUpload}
                style={{ display: "none" }}
              />
              <button
                className="save-button"
                type="button"
                onClick={() => rubricInputRef.current && rubricInputRef.current.click()}
              >
                Upload Rubric
              </button>
            </div>

            {// Show uploaded rubric filename}
            {rubricFileName && (
              <p style={{ marginTop: "10px", color: "#77232C", fontWeight: "bold" }}>
                Uploaded Rubric: {rubricFileName}
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
} 
*/

  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {loading ? (
        <div className="dashboard-content">
          <div className="loader-div">
            <MoonLoader size={50} color="#77232C" />
            <p>Analyzing video using: {selectedRubric}</p>
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {/* Video Upload */}
            {videoFile ? (
              <video controls>
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            ) : (
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange} 
              />
            )}

            {/* Rubric Selection */}
            <div className="rubric-controls">
              <select
                value={selectedRubric}
                onChange={(e) => setSelectedRubric(e.target.value)}
              >
                <option value="default.json">Default Rubric</option>
                {availableRubrics.map((rubric, index) => (
                  <option key={index} value={rubric.filename}>
                    {rubric.filename}
                  </option>
                ))}
              </select>

              <div className="rubric-upload">
                <input
                  ref={rubricInputRef}
                  type="file"
                  accept=".json,.yaml"
                  id="rubric-upload"
                  onChange={handleRubricUpload}
                  style={{ display: "none" }}
                />
                <button
                  className="save-button"
                  type="button"
                  onClick={() => rubricInputRef.current?.click()}
                >
                  Upload New Rubric
                </button>
              </div>
            </div>

            {/* Analyze Button */}
            <button 
              className="save-button" 
              onClick={handleAnalyze}
              disabled={!videoFile}
            >
              Analyze Video
            </button>

            {/* Rubric Upload Status */}
            {rubricFileName && (
              <p className="rubric-status">
                Active Rubric: {selectedRubric}
              </p>
            )}
          </div>

          {/* Analysis Results */}
          {status === "complete" && (
            <div className="analysis-results">
              <h2>Analysis Results</h2>

              <div className="result-section">
                <h3>Transcript</h3>
                <p>{transcript}</p>
              </div>

              <div className="result-section">
                <h3>AI Feedback</h3>
                <div className="feedback-content">
                  {feedback.split('\n').map((line, index) => (
                    <p key={index}>{line}</p>
                  ))}
                </div>
              </div>

              <div className="metrics-grid">
                <div className="metric-card">
                  <h4>Speech Rate</h4>
                  <p>{analysis.speech_rate_wps} WPS</p>
                </div>
                <div className="metric-card">
                  <h4>Eye Contact</h4>
                  <p>{analysis.eye_contact_ratio * 100}%</p>
                </div>
                {/* Add more metrics as needed */}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}


export default Upload;
